UPDATE COMMONCODE
   SET CODENAME_1 = #{name}
     , CODENAME_2 = #{type}
     , UNIT_PRICE = #{price}
     , CONTRIBUTION = #{contribution}
 WHERE COMMONCODE_NUMBER = #{code}
   AND COMMONCODE = 'P'
   AND USED = 'Y'

UPDATE PHYSICALTHERAPIST_BED
   SET BED_STATUS = '사용중'
 WHERE BED_CODE = #{bedCode}
   AND BED_STATUS= '사용가능'
   AND THERAPY_TYPE = #{therapyType}
